1	package retention
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	)
8	
9	// RegisterInput 是登记一份档案所需的信息。
10	//
11	// 编号和类别不能是空白；日期必须是 ParseDate 能解析的真实日期；
12	// 截止日可以与起算日相同，但不能更早。
13	type RegisterInput struct {
14		ID       string
15		Category string
16		Start    Date
17		End      Date
18	}
19	
20	// FreezeInput 是为档案新增一条冻结所需的信息。
21	type FreezeInput struct {
22		ArchiveID string
23		FreezeID  string
24		Reason    string
25		FrozenOn  Date
26	}
27	
28	// ReleaseInput 是解除一条冻结所需的信息。
29	type ReleaseInput struct {
30		ArchiveID  string
31		FreezeID   string
32		Reason     string
33		ReleasedOn Date
34	}
35	
36	// DestructionRequest 是一次销毁申请。
37	//
38	// 一次申请可以选择多个档案。申请编号在所有成功申请中唯一，
39	// 处理日期即判断档案是否到期所依据的日期。
40	type DestructionRequest struct {
41		ApplicationID string
42		ProcessedOn   Date
43		ArchiveIDs    []string
44	}
45	
46	// CheckRequest 是销毁前一次只做核对的请求，字段含义与 DestructionRequest 相同。
47	//
48	// 核对不销毁任何档案、不生成或改写清册，也不占用申请编号：
49	// 核对失败或发现阻碍后，仍可沿用同一编号继续核对或正式提交。
50	type CheckRequest struct {
51		ApplicationID string
52		ProcessedOn   Date
53		ArchiveIDs    []string
54	}
55	
56	// normalizeText 去除首尾空白；空白字段统一按空白处理，避免同值异写。
57	func normalizeText(s string) string { return strings.TrimSpace(s) }
58	
59	func requireText(value, name string) (string, error) {
60		v := normalizeText(value)
61		if v == "" {
62			return "", fmt.Errorf("retention: %s不能为空白: %w", name, ErrBlankField)
63		}
64		return v, nil
65	}
66	
67	func requireDate(d Date, name string) error {
68		if d.IsZero() {
69			return fmt.Errorf("retention: %s缺失或无效，应为 YYYY-MM-DD: %w", name, ErrInvalidDate)
70		}
71		return nil
72	}
73	
74	// Register 登记一份档案。
75	//
76	// 编号重复或任一输入无效时明确失败，并且不写盘，已有记录不受影响。
77	func (s *Store) Register(in RegisterInput) error {
78		id, err := requireText(in.ID, "档案编号")
79		if err != nil {
80			return err
81		}
82		category, err := requireText(in.Category, "类别")
83		if err != nil {
84			return err
85		}
86		if err := requireDate(in.Start, "起算日"); err != nil {
87			return err
88		}
89		if err := requireDate(in.End, "保管截止日"); err != nil {
90			return err
91		}
92		if in.End.Before(in.Start) {
93			return fmt.Errorf("retention: 档案 %s 的保管截止日 %s 早于起算日 %s: %w",
94				id, in.End, in.Start, ErrRetentionEndBeforeStart)
95		}
96		return s.mutate(func(data *storeData) error {
97			if _, exists := data.Archives[id]; exists {
98				return fmt.Errorf("retention: 档案编号 %s 已登记: %w", id, ErrDuplicateID)
99			}
100			data.Archives[id] = &archiveRecord{
101				ID:       id,
102				Category: category,
103				Start:    in.Start,
104				End:      in.End,
105				Freezes:  nil,
106			}
107			return nil
108		})
109	}
110	
111	// Freeze 为档案登记一条冻结。
112	//
113	// 冻结编号在同一档案内唯一。档案不存在、已销毁、冻结编号重复或输入无效时失败。
114	func (s *Store) Freeze(in FreezeInput) error {
115		archiveID, err := requireText(in.ArchiveID, "档案编号")
116		if err != nil {
117			return err
118		}
119		freezeID, err := requireText(in.FreezeID, "冻结编号")
120		if err != nil {
121			return err
122		}
123		reason, err := requireText(in.Reason, "冻结原因")
124		if err != nil {
125			return err
126		}
127		if err := requireDate(in.FrozenOn, "冻结日期"); err != nil {
128			return err
129		}
130		return s.mutate(func(data *storeData) error {
131			ar, ok := data.Archives[archiveID]
132			if !ok {
133				return fmt.Errorf("retention: 档案 %s 不存在，不能新增冻结: %w", archiveID, ErrNotFound)
134			}
135			if ar.Destroyed {
136				return fmt.Errorf("retention: 档案 %s 已销毁，不能新增冻结: %w", archiveID, ErrDestroyed)
137			}
138			for _, f := range ar.Freezes {
139				if f.ID == freezeID {
140					return fmt.Errorf("retention: 档案 %s 内冻结编号 %s 已存在: %w",
141						archiveID, freezeID, ErrDuplicateFreezeID)
142				}
143			}
144			ar.Freezes = append(ar.Freezes, &freezeRecord{
145				ID:       freezeID,
146				Reason:   reason,
147				FrozenOn: in.FrozenOn,
148			})
149			return nil
150		})
151	}
152	
153	// Release 解除一条冻结。
154	//
155	// 必须填写解除日期与原因，解除日期不能早于该冻结的冻结日期。
156	// 解除只在原记录上标记，不删除冻结记录，也不影响同一档案的其他冻结。
157	// 不能解除不存在或已经解除的冻结。
158	func (s *Store) Release(in ReleaseInput) error {
159		archiveID, err := requireText(in.ArchiveID, "档案编号")
160		if err != nil {
161			return err
162		}
163		freezeID, err := requireText(in.FreezeID, "冻结编号")
164		if err != nil {
165			return err
166		}
167		reason, err := requireText(in.Reason, "解除原因")
168		if err != nil {
169			return err
170		}
171		if err := requireDate(in.ReleasedOn, "解除日期"); err != nil {
172			return err
173		}
174		return s.mutate(func(data *storeData) error {
175			ar, ok := data.Archives[archiveID]
176			if !ok {
177				return fmt.Errorf("retention: 档案 %s 不存在: %w", archiveID, ErrNotFound)
178			}
179			var fr *freezeRecord
180			for _, f := range ar.Freezes {
181				if f.ID == freezeID {
182					fr = f
183					break
184				}
185			}
186			if fr == nil {
187				return fmt.Errorf("retention: 档案 %s 下冻结 %s 不存在: %w",
188					archiveID, freezeID, ErrFreezeNotFound)
189			}
190			if fr.Released {
191				return fmt.Errorf("retention: 档案 %s 的冻结 %s 已经解除，不能重复解除: %w",
192					archiveID, freezeID, ErrFreezeAlreadyReleased)
193			}
194			if in.ReleasedOn.Before(fr.FrozenOn) {
195				return fmt.Errorf("retention: 解除日期 %s 早于冻结 %s 的冻结日期 %s: %w",
196					in.ReleasedOn, freezeID, fr.FrozenOn, ErrReleaseBeforeFreeze)
197			}
198			fr.Released = true
199			fr.ReleaseReason = reason
200			releasedOn := in.ReleasedOn
201			fr.ReleasedOn = &releasedOn
202			return nil
203		})
204	}
205	
206	// Destroy 办理一次销毁申请。
207	//
208	// 只有名单中全部档案都存在、按处理日期已到期（处理日期不早于截止日，
209	// 截止日当天即到期）、未销毁且没有未解除冻结时，才会同时完成销毁，
210	// 并生成一份内容此后不可更改的已关闭清册。
211	//
212	// 名单为空、名单内编号重复或任一档案不符合条件时，整次申请失败，
213	// 不会留下部分销毁或清册。
214	//
215	// 同一申请编号此前已经成功办理时：处理日期与档案集合完全相同（顺序无关）
216	// 则返回原清册；沿用编号但改变日期或档案集合则失败。失败过的申请
217	// 在条件改变后可以用同一编号再次提交。
218	func (s *Store) Destroy(req DestructionRequest) (Manifest, error) {
219		applicationID, ids, seen, err := validateBatchInputs(req.ApplicationID, req.ProcessedOn, req.ArchiveIDs)
220		if err != nil {
221			return Manifest{}, err
222		}
223	
224		var result Manifest
225		err = s.mutate(func(data *storeData) error {
226			// 已成功的申请编号：幂等返回原清册，或因内容不一致失败。
227			if existing, ok := data.Manifests[applicationID]; ok {
228				if !sameApplication(existing, req.ProcessedOn, seen) {
229					return fmt.Errorf("retention: 申请编号 %s 已成功使用，本次日期或档案集合与原申请不一致: %w",
230						applicationID, ErrApplicationMismatch)
231				}
232				result = manifestFromRecord(existing)
233				return nil
234			}
235	
236			// 逐份校验，任一不符合条件则整体放弃（此时尚未改动任何记录）。
237			for _, id := range ids {
238				ar, ok := data.Archives[id]
239				if !ok {
240					return fmt.Errorf("retention: 档案 %s 不存在: %w", id, ErrNotFound)
241				}
242				if ar.Destroyed {
243					return fmt.Errorf("retention: 档案 %s 已在清册 %s 中，不能再次销毁: %w",
244						id, ar.ManifestID, ErrArchiveAlreadyOnManifest)
245				}
246				if req.ProcessedOn.Before(ar.End) {
247					return fmt.Errorf("retention: 档案 %s 尚未到期（截止日 %s，处理日期 %s）: %w",
248						id, ar.End, req.ProcessedOn, ErrNotExpired)
249				}
250				for _, f := range ar.Freezes {
251					if !f.Released {
252						return fmt.Errorf("retention: 档案 %s 有未解除的冻结 %s: %w",
253							id, f.ID, ErrActiveFreeze)
254					}
255				}
256			}
257	
258			// 全部满足：生成关闭清册，内容为各档案当时登记内容的快照。
259			rec := &manifestRecord{
260				ApplicationID: applicationID,
261				ProcessedOn:   req.ProcessedOn,
262			}
263			ordered := append([]string(nil), ids...)
264			sort.Strings(ordered)
265			for _, id := range ordered {
266				ar := data.Archives[id]
267				rec.Entries = append(rec.Entries, manifestEntry{
268					ID:       ar.ID,
269					Category: ar.Category,
270					Start:    ar.Start,
271					End:      ar.End,
272				})
273				ar.Destroyed = true
274				ar.ManifestID = applicationID
275			}
276			data.Manifests[applicationID] = rec
277			result = manifestFromRecord(rec)
278			return nil
279		})
280		if err != nil {
281			return Manifest{}, err
282		}
283		return result, nil
284	}
285	
286	// sameApplication 判断已成功申请与本次提交的处理日期和档案集合是否完全一致（顺序无关）。
287	func sameApplication(existing *manifestRecord, processedOn Date, idSet map[string]struct{}) bool {
288		if !existing.ProcessedOn.Equal(processedOn) {
289			return false
290		}
291		if len(existing.Entries) != len(idSet) {
292			return false
293		}
294		for _, e := range existing.Entries {
295			if _, ok := idSet[e.ID]; !ok {
296				return false
297			}
298		}
299		return true
300	}
301	
302	func manifestFromRecord(rec *manifestRecord) Manifest {
303		m := Manifest{
304			ApplicationID: rec.ApplicationID,
305			ProcessedOn:   rec.ProcessedOn,
306			Entries:       make([]ManifestEntry, 0, len(rec.Entries)),
307		}
308		for _, e := range rec.Entries {
309			m.Entries = append(m.Entries, ManifestEntry{
310				ID:       e.ID,
311				Category: e.Category,
312				Start:    e.Start,
313				End:      e.End,
314			})
315		}
316		return m
317	}
318	
319	func freezeFromRecord(fr *freezeRecord) FreezeRecord {
320		out := FreezeRecord{
321			ID:            fr.ID,
322			Reason:        fr.Reason,
323			FrozenOn:      fr.FrozenOn,
324			Released:      fr.Released,
325			ReleaseReason: fr.ReleaseReason,
326		}
327		if fr.ReleasedOn != nil {
328			out.ReleasedOn = *fr.ReleasedOn
329		}
330		return out
331	}
332	
333	// History 按档案编号核对完整历史。
334	//
335	// 结果包含登记内容、全部冻结及解除历史、当前未解除冻结、销毁状态以及
336	// 对应的已关闭清册。档案未登记时 found 为 false（err 为 nil），
337	// 这是明确的不存在结果。
338	func (s *Store) History(archiveID string) (h ArchiveHistory, found bool, err error) {
339		id := normalizeText(archiveID)
340		if id == "" {
341			return ArchiveHistory{}, false, fmt.Errorf("retention: 档案编号不能为空白: %w", ErrBlankField)
342		}
343		err = s.view(func(data *storeData) error {
344			ar, ok := data.Archives[id]
345			if !ok {
346				return nil
347			}
348			found = true
349			h = ArchiveHistory{
350				ID:                    ar.ID,
351				Category:              ar.Category,
352				Start:                 ar.Start,
353				RetentionEnd:          ar.End,
354				Destroyed:             ar.Destroyed,
355				ManifestApplicationID: ar.ManifestID,
356				Freezes:               make([]FreezeRecord, 0, len(ar.Freezes)),
357			}
358			for _, fr := range ar.Freezes {
359				view := freezeFromRecord(fr)
360				h.Freezes = append(h.Freezes, view)
361				if !fr.Released {
362					h.ActiveFreezes = append(h.ActiveFreezes, view)
363				}
364			}
365			if ar.Destroyed && ar.ManifestID != "" {
366				if rec, ok := data.Manifests[ar.ManifestID]; ok {
367					m := manifestFromRecord(rec)
368					h.Manifest = &m
369				}
370			}
371			return nil
372		})
373		if err != nil {
374			return ArchiveHistory{}, false, err
375		}
376		return h, found, nil
377	}
378	
379	// Manifest 按申请编号查询一份已关闭清册。不存在时 found 为 false。
380	func (s *Store) GetManifest(applicationID string) (m Manifest, found bool, err error) {
381		id := normalizeText(applicationID)
382		if id == "" {
383			return Manifest{}, false, fmt.Errorf("retention: 申请编号不能为空白: %w", ErrBlankField)
384		}
385		err = s.view(func(data *storeData) error {
386			if rec, ok := data.Manifests[id]; ok {
387				m = manifestFromRecord(rec)
388				found = true
389			}
390			return nil
391		})
392		if err != nil {
393			return Manifest{}, false, err
394		}
395		return m, found, nil
396	}
397

