11		if err != nil {
12			t.Fatalf("打开保管库失败: %v", err)
13		}
14		t.Cleanup(func() { _ = s.Close() })
15		return s
16	}
17	
18	func reg(t *testing.T, s *Store, id, category, start, end string) {
19		t.Helper()
20		err := s.Register(RegisterInput{
21			ID:       id,
22			Category: category,
23			Start:    MustParseDate(start),
24			End:      MustParseDate(end),
25		})
26		if err != nil {
27			t.Fatalf("登记 %s 失败: %v", id, err)
28		}
