31	func TestRegisterValidation(t *testing.T) {
32		s := openTestStore(t)
33	
34		valid := RegisterInput{
35			ID:       "A-001",
36			Category: "合同",
37			Start:    MustParseDate("2020-01-01"),
38			End:      MustParseDate("2025-01-01"),
39		}
40		if err := s.Register(valid); err != nil {
41			t.Fatalf("正常登记失败: %v", err)
42		}
43	
44		// 重复编号失败。
45		if err := s.Register(valid); !errors.Is(err, ErrDuplicateID) {
46			t.Fatalf("重复编号应失败 ErrDuplicateID，得到 %v", err)
47		}
48	
49		// 编号或类别为空白（含纯空格）。
50		for _, blank := range []string{"", "   ", "\t"} {
51			in := valid
52			in.ID = blank
53			if err := s.Register(in); !errors.Is(err, ErrBlankField) {
54				t.Fatalf("空白编号 %q 应失败，得到 %v", blank, err)
55			}
56			in = valid
57			in.Category = blank
58			if err := s.Register(in); !errors.Is(err, ErrBlankField) {
59				t.Fatalf("空白类别 %q 应失败，得到 %v", blank, err)
60			}
61		}
62	
63		// 截止日早于起算日（含同一天合法）。
64		early := valid
65		early.ID = "A-002"
66		early.End = MustParseDate("2019-12-31")
67		if err := s.Register(early); !errors.Is(err, ErrRetentionEndBeforeStart) {
68			t.Fatalf("截止日早于起算日应失败，得到 %v", err)
69		}
70		same := valid
71		same.ID = "A-003"
72		same.Start = MustParseDate("2022-06-06")
73		same.End = MustParseDate("2022-06-06")
74		if err := s.Register(same); err != nil {
75			t.Fatalf("截止日等于起算日应允许，得到 %v", err)
76		}
77	
78		// 各类失败后，已有记录仍可核对，且失败编号未被占用。
79		if _, found, err := s.History("A-001"); err != nil || !found {
80			t.Fatalf("失败后已有记录应仍可查，found=%v err=%v", found, err)
81		}
82		retry := valid
83		retry.ID = "A-002"
84		if err := s.Register(retry); err != nil {
85			t.Fatalf("此前失败的编号应仍可登记，得到 %v", err)
86		}
87	}
88	
89	func TestRegisterZeroDateRejected(t *testing.T) {
90		s := openTestStore(t)
91		err := s.Register(RegisterInput{ID: "X", Category: "C", End: MustParseDate("2025-01-01")})
92		if !errors.Is(err, ErrInvalidDate) {
93			t.Fatalf("缺失起算日应失败，得到 %v", err)
94		}
95	}
96	
97	func TestFreezeAndRelease(t *testing.T) {
98		s := openTestStore(t)
99		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-01")
100	
101		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-02")}); err != nil {
102			t.Fatalf("新增冻结失败: %v", err)
103		}
104		// 同档案内冻结编号唯一；不同档案允许同号。
105		reg(t, s, "A-2", "合同", "2020-01-01", "2025-01-01")
106		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "再次", FrozenOn: MustParseDate("2025-01-03")}); !errors.Is(err, ErrDuplicateFreezeID) {
107			t.Fatalf("重复冻结编号应失败，得到 %v", err)
108		}
109		if err := s.Freeze(FreezeInput{ArchiveID: "A-2", FreezeID: "F-1", Reason: "另案", FrozenOn: MustParseDate("2025-01-03")}); err != nil {
110			t.Fatalf("不同档案使用相同冻结编号应允许，得到 %v", err)
111		}
112		// 再给 A-1 一条冻结，验证多条互不影响。
113		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计", FrozenOn: MustParseDate("2025-01-04")}); err != nil {
114			t.Fatalf("第二条冻结失败: %v", err)
115		}
116	
117		// 不存在 / 空白原因 / 空白编号。
118		if err := s.Freeze(FreezeInput{ArchiveID: "NOPE", FreezeID: "F", Reason: "r", FrozenOn: MustParseDate("2025-01-02")}); !errors.Is(err, ErrNotFound) {
119			t.Fatalf("给不存在档案冻结应失败，得到 %v", err)
120		}
121		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-3", Reason: "  ", FrozenOn: MustParseDate("2025-01-02")}); !errors.Is(err, ErrBlankField) {
122			t.Fatalf("空白冻结原因应失败，得到 %v", err)
123		}
124	
125		// 解除日期不能早于冻结日期。
126		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-01")}); !errors.Is(err, ErrReleaseBeforeFreeze) {
127			t.Fatalf("解除日期早于冻结日期应失败，得到 %v", err)
128		}
129		// 解除不存在或已解除的冻结。
130		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "NOPE", Reason: "x", ReleasedOn: MustParseDate("2025-02-01")}); !errors.Is(err, ErrFreezeNotFound) {
131			t.Fatalf("解除不存在冻结应失败，得到 %v", err)
132		}
133		if err := s.Release(ReleaseInput{ArchiveID: "NOPE", FreezeID: "F-1", Reason: "x", ReleasedOn: MustParseDate("2025-02-01")}); !errors.Is(err, ErrNotFound) {
134			t.Fatalf("解除不存在档案的冻结应失败，得到 %v", err)
135		}
136		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "  ", ReleasedOn: MustParseDate("2025-02-01")}); !errors.Is(err, ErrBlankField) {
137			t.Fatalf("空白解除原因应失败，得到 %v", err)
138		}
139	
140		// 正常解除 F-1（解除日期等于冻结日期合法）；F-2 仍然挂着。
141		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-02")}); err != nil {
142			t.Fatalf("解除冻结失败: %v", err)
143		}
144		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "再结一次", ReleasedOn: MustParseDate("2025-01-05")}); !errors.Is(err, ErrFreezeAlreadyReleased) {
145			t.Fatalf("重复解除应失败，得到 %v", err)
146		}
147	
148		h, found, err := s.History("A-1")
149		if err != nil || !found {
150			t.Fatalf("核对失败: %v %v", found, err)
151		}
152		if len(h.Freezes) != 2 {
153			t.Fatalf("全部冻结历史应保留 2 条，得到 %d", len(h.Freezes))
154		}
155		if len(h.ActiveFreezes) != 1 || h.ActiveFreezes[0].ID != "F-2" {
156			t.Fatalf("应只剩 F-2 未解除，得到 %+v", h.ActiveFreezes)
157		}
158		f1 := h.Freezes[0]
159		if !f1.Released || f1.ReleaseReason != "结案" || !f1.ReleasedOn.Equal(MustParseDate("2025-01-02")) {
160			t.Fatalf("F-1 解除信息不正确: %+v", f1)
161		}
162	}
