222		if _, err := s.Destroy(DestructionRequest{ApplicationID: "APP", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1", "A-2", "A-3"}}); !errors.Is(err, ErrActiveFreeze) {
