255		before := mustCheck(t, s, "APP-1", "2025-01-10", "A-1")
256		if before.Status != CheckReady {
257			t.Fatalf("前置核对应可以办理，得到 %s", before.Status)
258		}
259		// 核对不销毁、不产生清册。
260		h, found, _ := s.History("A-1")
261		if !found || h.Destroyed {
262			t.Fatalf("核对不应销毁档案: %+v", h)
263		}
264		if _, found, err := s.GetManifest("APP-1"); err != nil || found {
265			t.Fatalf("核对不应生成清册，found=%v err=%v", found, err)
266		}
267	
268		// 核对不占用申请编号：随后同编号正式提交成功。
269		m, err := s.Destroy(DestructionRequest{
270			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
271		})
272		if err != nil {
273			t.Fatalf("核对后同编号应仍可正式提交: %v", err)
274		}
275		if m.ApplicationID != "APP-1" {
276			t.Fatalf("正式提交清册不正确: %+v", m)
277		}
278	
279		// 报告只说明核对当时情况：此前可办的核对之后新增冻结，再次正式提交须按最新状态受阻。
280		s2 := openTestStore(t)
281		reg(t, s2, "B-1", "合同", "2020-01-01", "2025-01-10")
282		if r := mustCheck(t, s2, "APP-B", "2025-01-10", "B-1"); r.Status != CheckReady {
283			t.Fatalf("前置核对应可以办理，得到 %s", r.Status)
284		}
285		if err := s2.Freeze(FreezeInput{ArchiveID: "B-1", FreezeID: "F", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-10")}); err != nil {
286			t.Fatal(err)
287		}
288		if _, err := s2.Destroy(DestructionRequest{
289			ApplicationID: "APP-B", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"B-1"},
290		}); !errors.Is(err, ErrActiveFreeze) {
291			t.Fatalf("核对后新增冻结，正式提交应按最新状态被阻止，得到 %v", err)
292		}
293	}
294	
295	func TestCheckFailureAfterCorruptionDoesNotReturnStaleReport(t *testing.T) {
296		dir := t.TempDir()
297		s, err := Open(dir)
298		if err != nil {
299			t.Fatal(err)
300		}
301		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
302		// 先有一次成功核对，调用者手里持有旧报告。
303		old := mustCheck(t, s, "APP-1", "2025-01-10", "A-1")
304		if old.Status != CheckReady {
305			t.Fatalf("前置核对应成功: %+v", old)
306		}
307	
308		// 本地记录随后损坏：再次核对必须明确失败，不能拿旧报告充当本次结果。
309		if err := os.WriteFile(s.statePath(), []byte("{这不是合法JSON"), 0o600); err != nil {
310			t.Fatal(err)
311		}
312		if _, err := s.Check(CheckRequest{
313			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
314		}); err == nil {
315			t.Fatal("状态文件损坏时核对应明确失败")
316		}
317	}
318	
319	func TestCheckReportIsDetachedCopy(t *testing.T) {
320		s := openTestStore(t)
321		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
322		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-01-10")
323		if _, err := s.Destroy(DestructionRequest{
324			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"),
325			ArchiveIDs: []string{"A-1", "A-2"},
326		}); err != nil {
327			t.Fatal(err)
328		}
329	
330		r := mustCheck(t, s, "APP-1", "2025-01-10", "A-1", "A-2")
331		if r.Status != CheckReplayable || r.Manifest == nil {
332			t.Fatalf("前置条件不正确: %+v", r)
333		}
334		// 调用者修改返回报告及其中清册。
335		r.Manifest.ApplicationID = "HACK"
336		r.Manifest.Entries[0].Category = "被篡改"
337		r.Manifest.Entries = r.Manifest.Entries[:1]
338	
339		// 保存的历史不受影响。
340		m, found, err := s.GetManifest("APP-1")
341		if err != nil || !found {
342			t.Fatalf("原清册应仍可查: found=%v err=%v", found, err)
343		}
344		if m.ApplicationID != "APP-1" || len(m.Entries) != 2 || m.Entries[0].Category != "合同" {
345			t.Fatalf("修改报告不得影响保存的清册: %+v", m)
346		}
347		h, _, _ := s.History("A-1")
348		if h.Manifest == nil || h.Manifest.ApplicationID != "APP-1" {
349			t.Fatalf("历史中清册不应受报告修改影响: %+v", h.Manifest)
350		}
351	}
352	
353	// TestCheckSnapshotConsistencyUnderConcurrency 验证多个本机程序并发办理时，
354	// 同一份报告里的档案与清册必定来自同一个已保存状态：A-1、A-2 在一次销毁中
355	// 原子地进入同一份清册，因此任何一次核对看到的两者销毁状态必须一致，
356	// 且已销毁时所属清册信息必定同时可见。
357	func TestCheckSnapshotConsistencyUnderConcurrency(t *testing.T) {
358		dir := t.TempDir()
359		setup, err := Open(dir)
360		if err != nil {
361			t.Fatal(err)
362		}
363		reg(t, setup, "A-1", "合同", "2020-01-01", "2025-01-10")
364		reg(t, setup, "A-2", "凭证", "2020-01-01", "2025-01-10")
365		if err := setup.Close(); err != nil {
366			t.Fatal(err)
367		}
368	
369		const readers = 8
370		const iterations = 500
371		var wg sync.WaitGroup
372		start := make(chan struct{})
373		var failures int64
374	
375		// 读者们持续核对：一个用未使用编号看逐份状态，一个直接核对已成功编号。
376		for i := 0; i < readers; i++ {
377			wg.Add(1)
378			go func() {
379				defer wg.Done()
380				sr, err := Open(dir)
381				if err != nil {
382					atomic.AddInt64(&failures, 1)
383					return
384				}
385				defer sr.Close()
386				<-start
387				for k := 0; k < iterations; k++ {
388					r, err := sr.Check(CheckRequest{
389						ApplicationID: "APP-R", ProcessedOn: MustParseDate("2025-01-10"),
390						ArchiveIDs: []string{"A-1", "A-2"},
391					})
392					if err != nil {
393						atomic.AddInt64(&failures, 1)
394						return
395					}
396					if r.Status != CheckReady && r.Status != CheckBlocked {
397						t.Errorf("未使用编号核对只应可以办理或存在阻碍，得到 %s", r.Status)
398						return
399					}
400					if len(r.Results) != 2 {
401						t.Errorf("报告应含两份档案，得到 %d", len(r.Results))
402						return
403					}
404					d1, d2 := r.Results[0].Destroyed, r.Results[1].Destroyed
405					if d1 != d2 {
406						t.Errorf("报告混入了销毁前后的不同状态: %+v", r.Results)
407						return
408					}
409					if d1 {
410						for _, res := range r.Results {
411							obs := res.Obstructions
412							if len(obs) != 1 || obs[0].Kind != ObstructionDestroyed ||
413								obs[0].ManifestApplicationID != "APP-1" ||
414								!obs[0].ProcessedOn.Equal(MustParseDate("2025-01-10")) {
415								t.Errorf("已销毁档案的所属清册必须与状态同快照可见: %+v", obs)
416								return
417							}
418						}
419					}
420	
421					// 直接核对该已成功编号：要么尚未生成（可以办理且无清册），
422					// 要么可以取回原清册，二者必居其一，不能出现半生成状态。
423					rr, err := sr.Check(CheckRequest{
424						ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"),
425						ArchiveIDs: []string{"A-2", "A-1"},
426					})
427					if err != nil {
428						t.Errorf("核对已成功编号不应失败: %v", err)
429						return
430					}
431					switch rr.Status {
432					case CheckReady:
433						if rr.Manifest != nil {
434							t.Errorf("可以办理时不应带清册: %+v", rr.Manifest)
435							return
436						}
437					case CheckReplayable:
438						if rr.Manifest == nil || len(rr.Manifest.Entries) != 2 {
439							t.Errorf("可取回时原清册必须完整: %+v", rr.Manifest)
440							return
441						}
442					default:
443						t.Errorf("已成功编号不应出现其他状态: %s", rr.Status)
444						return
445					}
446				}
447			}()
448		}
449	
450		// 办理者在读者开始后销毁两份档案（单次原子办理）。
451		wg.Add(1)
452		go func() {
453			defer wg.Done()
454			sm, err := Open(dir)
455			if err != nil {
456				atomic.AddInt64(&failures, 1)
457				close(start)
458				return
459			}
460			defer sm.Close()
461			close(start)
462			if _, err := sm.Destroy(DestructionRequest{
463				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"),
464				ArchiveIDs: []string{"A-1", "A-2"},
465			}); err != nil {
466				t.Errorf("并发销毁失败: %v", err)
467			}
468		}()
469		wg.Wait()
470	
471		if atomic.LoadInt64(&failures) != 0 {
472			t.Fatalf("并发核对中出现打开失败等错误")
473		}
474	}
