205	func runHelper(t *testing.T, dir, op, freezeID string) helperResult {
206		t.Helper()
207		cmd := exec.Command(os.Args[0], "-test.run=TestSubprocessHelper", "-test.v")
208		cmd.Env = append(os.Environ(),
209			"RETENTION_HELPER_DIR="+dir,
