207	// Revise 修订档案的保管截止日。
208	//
209	// 调用者发现登记的期限需要调整时，可以对尚未销毁的档案延长或缩短截止日，
210	// 不必重新登记；编号、类别与起算日均不可改动。被冻结的档案也允许修订期限，
211	// 但修订不能解除冻结，期限缩短后仍须满足原有冻结规则才能销毁。
212	//
213	// 每次提交包含修订编号、档案编号、调用者看到的原截止日、新截止日、修订日期和原因。
214	// 修订编号与原因去首尾空白后不得为空；日期沿用真实日历日期规则。新截止日不能早于
215	// 起算日，也不能等于所提交的原截止日。修订日期仅用于记录，提交成功即采用新期限。
216	//
217	// 首次办理时，所提交的原截止日必须与当前保存值相同，否则返回可区分的期限已变化错误
218	// （ErrRevisionEndMismatch）并提供当前截止日，不能覆盖他人的修改。
219	//
220	// 修订编号在同一保管库的全部档案之间唯一，且与销毁申请编号互不占用。同编号且提交
221	// 内容相同的重试只返回第一次成功的记录，不增加历史；即使后来再次改过期限或档案已被
222	// 销毁，这次重试仍能取回原记录。沿用成功编号改变任何一项内容时返回编号冲突
223	// （ErrDuplicateRevisionID）。失败过的编号仍可用于重新提交。
224	//
225	// 任何失败都不改变期限或留下修订历史。返回值是复制生成的只读视图，调用者修改不影响
226	// 保管库中保存的记录。
227	func (s *Store) Revise(in RevisionInput) (RevisionRecord, error) {
228		revisionID, err := requireText(in.RevisionID, "修订编号")
229		if err != nil {
230			return RevisionRecord{}, err
231		}
232		archiveID, err := requireText(in.ArchiveID, "档案编号")
233		if err != nil {
234			return RevisionRecord{}, err
235		}
236		reason, err := requireText(in.Reason, "修订原因")
237		if err != nil {
238			return RevisionRecord{}, err
239		}
240		if err := requireDate(in.RevisedOn, "修订日期"); err != nil {
241			return RevisionRecord{}, err
242		}
243		if err := requireDate(in.OriginalEnd, "原截止日"); err != nil {
244			return RevisionRecord{}, err
245		}
246		if err := requireDate(in.NewEnd, "新截止日"); err != nil {
247			return RevisionRecord{}, err
248		}
249		if in.NewEnd.Equal(in.OriginalEnd) {
250			return RevisionRecord{}, fmt.Errorf("retention: 档案 %s 修订后的新截止日 %s 与原截止日相同: %w",
251				archiveID, in.NewEnd, ErrRevisionEndUnchanged)
252		}
253	
254		var result RevisionRecord
255		err = s.mutate(func(data *storeData) error {
256			// 幂等：修订编号已成功使用时，内容完全相同则返回第一次成功的记录，否则编号冲突。
257			// 取回原记录不依赖档案当前状态，即使期限后来被再次修改或档案已销毁也不受影响。
258			if existing, ok := data.Revisions[revisionID]; ok {
259				if !sameRevision(existing, in, archiveID, reason) {
260					return fmt.Errorf("retention: 修订编号 %s 已成功使用，本次提交内容与原修订不一致: %w",
261						revisionID, ErrDuplicateRevisionID)
262				}
263				result = revisionFromRecord(existing)
264				return nil
265			}
266			// 修订编号与销毁申请编号互不占用。
267			if _, ok := data.Manifests[revisionID]; ok {
268				return fmt.Errorf("retention: 修订编号 %s 已被销毁申请使用: %w",
269					revisionID, ErrRevisionIDUsedByManifest)
270			}
271			ar, ok := data.Archives[archiveID]
272			if !ok {
273				return fmt.Errorf("retention: 档案 %s 不存在，不能修订保管截止日: %w",
274					archiveID, ErrNotFound)
275			}
276			if ar.Destroyed {
277				return fmt.Errorf("retention: 档案 %s 已销毁，不能修订保管截止日: %w",
278					archiveID, ErrDestroyed)
279			}
280			if in.NewEnd.Before(ar.Start) {
281				return fmt.Errorf("retention: 档案 %s 修订后的保管截止日 %s 早于起算日 %s: %w",
282					archiveID, in.NewEnd, ar.Start, ErrRetentionEndBeforeStart)
283			}
284			// 乐观核对：提交的原截止日必须与当前保存值一致，避免覆盖他人的修改。
285			if !in.OriginalEnd.Equal(ar.End) {
286				return &RevisionEndMismatchError{
287					ArchiveID: archiveID,
288					Submitted: in.OriginalEnd,
289					Current:   ar.End,
290				}
291			}
292			rec := &revisionRecord{
293				RevisionID:  revisionID,
294				ArchiveID:   archiveID,
295				OriginalEnd: in.OriginalEnd,
296				NewEnd:      in.NewEnd,
297				RevisedOn:   in.RevisedOn,
298				Reason:      reason,
299			}
300			data.Revisions[revisionID] = rec

