type helperResult struct {
	op      string
	failed  bool
	message string
}

func runHelper(t *testing.T, dir, op, freezeID string) helperResult {
	t.Helper()
	cmd := exec.Command(os.Args[0], "-test.run=TestSubprocessHelper", "-test.v")
	cmd.Env = append(os.Environ(),
